/// Boards needed to cut every piece from stock of one length: first-fit decreasing with a 1/8 in kerf,
/// so short cuts (cripples, blocking, header plies) come out of shared boards the way a framer cuts them.
pub fn stock_boards(lengths:&[f64],stock:f64)->usize{
 let kerf=0.125/12.;let mut cuts:Vec<f64>=lengths.iter().map(|l|l.max(0.)).collect();cuts.sort_by(|a,b|b.total_cmp(a));let mut left:Vec<f64>=vec![];
 for l in cuts{if l>=stock-1e-6{left.push(0.);continue}if let Some(r)=left.iter_mut().find(|r|**r+1e-9>=l+kerf){*r-=l+kerf;}else{left.push(stock-l-kerf);}}
 left.len()
}
